/// Embeds the example packs (`../examples/packs`) into
/// `lib/config/starter_packs.g.dart` as data-folder files, laid out the way
/// examples/packs/README.md installs them: `pack.json` and `behaviors/` under
/// `packs/<pack>/`, NPC definitions, shops and GUIs at the data folder root.
/// The editor seeds a starter workspace from them without a network request.
///
///   dart run tool/embed_starter_packs.dart          # rewrite the generated file
///   dart run tool/embed_starter_packs.dart --check  # exit 1 when it is stale
library;

import 'dart:io';

const String starterPacksPath = 'lib/config/starter_packs.g.dart';

/// Where a file of an example pack goes in a data folder, or null for files
/// that are not installed (the README).
String? starterPath(String pack, String relative) {
  if (relative == 'pack.json' || relative.startsWith('behaviors/')) return 'packs/$pack/$relative';
  if (relative.startsWith('npcs/') || relative.startsWith('shops/') || relative.startsWith('gui/')) return relative;
  return null;
}

/// Every installed example-pack file by data-folder path.
Map<String, String> readStarterPacks(Directory packsDirectory) {
  final Map<String, String> files = <String, String>{};
  final List<Directory> packs = packsDirectory.listSync().whereType<Directory>().toList()
    ..sort((Directory a, Directory b) => a.path.compareTo(b.path));
  for (final Directory pack in packs) {
    final String name = pack.uri.pathSegments.where((String segment) => segment.isNotEmpty).last;
    for (final File file in pack.listSync(recursive: true).whereType<File>()) {
      if (!file.path.endsWith('.json')) continue;
      final String relative = file.path.substring(pack.path.length + 1).replaceAll(r'\', '/');
      final String? target = starterPath(name, relative);
      if (target == null) continue;
      if (files.containsKey(target)) throw StateError('Two example packs install $target');
      files[target] = file.readAsStringSync();
    }
  }
  return files;
}

String renderStarterPacks(Map<String, String> files) {
  final List<String> keys = files.keys.toList()..sort();
  final StringBuffer out = StringBuffer()
    ..writeln('// GENERATED by tool/embed_starter_packs.dart from ../examples/packs. Do not edit.')
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// The example packs as data-folder files, by path.')
    ..writeln('const Map<String, String> starterPackFiles = <String, String>{');
  for (final String key in keys) {
    final String source = files[key]!;
    if (source.contains("'''")) throw StateError("$key contains ''' and cannot be embedded");
    out
      ..writeln("  '$key': r'''")
      ..write(source)
      ..writeln("''',");
  }
  out.writeln('};');
  return out.toString();
}

void main(List<String> arguments) {
  final Directory packs = Directory('../examples/packs');
  if (!packs.existsSync()) {
    stderr.writeln('Run from animus-web/; ../examples/packs is missing.');
    exit(2);
  }
  final String rendered = renderStarterPacks(readStarterPacks(packs));
  final File target = File(starterPacksPath);
  if (arguments.contains('--check')) {
    if (!target.existsSync() || target.readAsStringSync() != rendered) {
      stderr.writeln('$starterPacksPath is stale; run dart run tool/embed_starter_packs.dart');
      exit(1);
    }
    return;
  }
  target.writeAsStringSync(rendered);
  stdout.writeln('Wrote $starterPacksPath (${rendered.length} bytes).');
}
